      pt: ["Centro de criação de gado Ankole.", "Importante local de produção de leite.", "A sede é Kabarore.", "Faz fronteira com o Parque Nacional de Akagera.", "Paisagem típica de savana com colinas suaves.", "Caracterizado pela pecuária e agricultura."],
      fr: ["Centre d'élevage des bovins Ankole.", "Important centre de production laitière.", "Le chef-lieu est Kabarore.", "Frontalier du parc national de l'Akagera.", "Paysage de savane typique aux collines douces.", "Économie basée sur l'élevage et les cultures vivrières."],
